<?php require '../includes/bootstrap.php';student_required();$sid=$_SESSION['student_id'];$events=$pdo->query("SELECT COUNT(*) FROM events WHERE status IN ('OPEN','UPCOMING')")->fetchColumn();$problems=$pdo->query("SELECT COUNT(*) FROM problem_statements WHERE status='AVAILABLE'")->fetchColumn();$s=$pdo->prepare("SELECT s.*,p.problem_code,p.title,e.event_name FROM selections s JOIN problem_statements p ON p.problem_id=s.problem_id JOIN events e ON e.event_id=p.event_id WHERE s.student_id=?");$s->execute([$sid]);$selection=$s->fetch();$tm=$pdo->prepare('SELECT t.* FROM team_members m JOIN teams t ON t.team_id=m.team_id WHERE m.student_id=? LIMIT 1');$tm->execute([$sid]);$team=$tm->fetch();$title='Dashboard';$base='../';$nav='<a href="problems.php">Problems</a><a href="team.php">Team</a><a href="history.php">History</a><a href="../logout.php">Logout</a>';include '../includes/header.php';?><div class="row"><div><h1>Welcome, <?=e($_SESSION['student_name'])?></h1><p class="muted">Your hackathon command center.</p></div></div><div class="grid"><div class="card"><div class="stat"><?=e($events)?></div><p class="muted">Open / upcoming events</p></div><div class="card"><div class="stat"><?=e($problems)?></div><p class="muted">Available problems</p></div><div class="card"><div class="stat"><?=$team?'1':'0'?></div><p class="muted">Your team</p></div></div><h2>Current selection</h2><div class="card"><?php if($selection):?><span class="badge"><?=e($selection['status'])?></span><h3><?=e($selection['problem_code'])?> · <?=e($selection['title'])?></h3><p class="muted"><?=e($selection['event_name'])?></p><a class="btn secondary" href="problems.php">Change selection</a><?php else:?><h3>No problem selected yet</h3><p class="muted">Explore available problem statements and choose one.</p><a class="btn" href="problems.php">Explore Problems</a><?php endif;?></div><?php include '../includes/footer.php';?>
